-- Function: public.sp_get_monthly_teacher_attendance
-- Backup generated on 2026-11-11 09:05:52

CREATE OR REPLACE PROCEDURE public.sp_get_monthly_teacher_attendance(IN p_tenant_id uuid, IN p_branch_id uuid, IN p_year integer, IN p_month integer, INOUT cur refcursor DEFAULT 'cur_monthly_teacher_attendance'::refcursor)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_start_date date := make_date(p_year, p_month, 1);     v_end_date date := (make_date(p_year, p_month, 1) + interval '1 month - 1 day')::date; BEGIN     OPEN cur FOR     WITH eligible_teachers AS (         SELECT DISTINCT t.id AS teacher_id,                t.employee_number::VARCHAR(50) AS employee_number,                t.first_name::VARCHAR(100) AS first_name,                t.last_name::VARCHAR(100) AS last_name,                TRIM(t.first_name || ' ' || COALESCE(t.last_name, ''))::VARCHAR(200) AS full_name,                t.profile_photo_url,                COALESCE(te.job_title, 'Educator')::VARCHAR(100) AS job_title         FROM teachers t         LEFT JOIN user_branch_assignments uba ON t.user_id = uba.user_id AND uba.revoked_at IS NULL         LEFT JOIN teacher_employments te ON t.id = te.teacher_id         WHERE t.tenant_id = p_tenant_id           AND (               uba.branch_id = p_branch_id               OR te.branch_id = p_branch_id               OR EXISTS (                   SELECT 1 FROM teacher_attendance ta                    WHERE ta.teacher_id = t.id AND ta.branch_id = p_branch_id               )               OR EXISTS (                   SELECT 1 FROM classroom_teachers ct                    JOIN classrooms cr ON ct.classroom_id = cr.id                    WHERE ct.user_id = t.user_id AND cr.branch_id = p_branch_id               )           )     ),     deduped_attendance AS (         SELECT DISTINCT ON (ta.teacher_id, ta.attendance_date)             ta.id AS attendance_id,             ta.teacher_id,             ta.branch_id,             ta.attendance_date,             EXTRACT(DAY FROM ta.attendance_date)::INTEGER AS day_of_month,             ta.status::VARCHAR(50) AS status,             ta.clock_in_time,             ta.clock_out_time,             ta.notes         FROM teacher_attendance ta         WHERE ta.tenant_id = p_tenant_id           AND ta.branch_id = p_branch_id           AND ta.attendance_date >= v_start_date           AND ta.attendance_date <= v_end_date         ORDER BY ta.teacher_id, ta.attendance_date, ta.updated_at DESC, ta.created_at DESC     )     SELECT          et.teacher_id,         et.employee_number,         et.first_name,         et.last_name,         et.full_name,         et.job_title,         et.profile_photo_url,         da.attendance_id,         da.attendance_date,         da.day_of_month,         da.status,         da.clock_in_time,         da.clock_out_time,         da.notes     FROM eligible_teachers et     LEFT JOIN deduped_attendance da ON et.teacher_id = da.teacher_id     ORDER BY et.full_name, da.day_of_month NULLS LAST; END; $procedure$ ;
